    "difficulty": 3,
    "stem": "A 74-year-old man is evaluated in the emergency department of Montreal General Hospital with clinical findings indicative of CMPA Medical Decision-Making Capacity and Substitute Decision Maker Hierarchy. Clinical examination and investigative review confirm hierarchy starting with court-appointed guardian, spouse/partner, adult child, parent, sibling. Vitals reveal blood pressure of 136/76 mm Hg, heart rate of 76/min, respiratory rate of 18/min, and temperature of 37.8C (98.3F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of cmpa medical decision-making capacity and substitute decision maker hierarchy. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
    "options": [
      {
        "text": "Oral broad-spectrum fluoroquinolone monotherapy without microbiological confirmation",
        "correct": false,
        "explanation": "Incorrect: Empiric fluoroquinolones risk severe adverse effects including tendonopathy and select for multidrug-resistant pathogens when unindicated."
      },
      {
        "text": "Hierarchy starting with court-appointed guardian, spouse/partner, adult child, parent, sibling",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is hierarchy starting with court-appointed guardian, spouse/partner, adult child, parent, sibling. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Oral bisphosphonate administration during active hypocalcemia",
        "correct": false,
        "explanation": "Incorrect: Potent osteoclast inhibition in hypocalcemic states triggers life-threatening cardiac arrhythmias, tetany, and laryngeal spasm."
      },
      {
        "text": "Intensive intravenous insulin bolus therapy without baseline potassium evaluation",
        "correct": false,
        "explanation": "Incorrect: Rapid insulin infusion shifts extracellular potassium intracellularly, precipitating lethal hypokalemia-induced cardiac arrest."
      },
      {
        "text": "Diagnostic lumbar puncture prior to excluding intracranial mass effect with neuroimaging",
        "correct": false,
        "explanation": "Incorrect: Performing dural puncture in the presence of focal space-occupying lesions risks fatal transtentorial or tonsillar herniation."
      }
    ],
