    "stem": "A 44-year-old man is examined in the clinical examination center for Medical Council of Canada Qualifying Examination review with clinical findings indicative of Canadian Thoracic Society COPD Triple Inhalation Therapy Criteria. Clinical examination and investigative review confirm LAMA/LABA/ICS single-inhaler triple therapy for frequent exacerbators with blood eosinophils >= 300 cells/uL. Vitals reveal blood pressure of 119/81 mm Hg, heart rate of 81/min, respiratory rate of 15/min, and temperature of 38.3C (98.8F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of canadian thoracic society copd triple inhalation therapy criteria. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
