    "stem": "A 34-year-old man is admitted to the inpatient teaching service at The Ottawa Hospital with clinical findings indicative of SOGC Placenta Previa Elective Cesarean Section Delivery Timing. Clinical examination and investigative review confirm planned delivery at 36+0 to 37+6 weeks gestation in stable asymptomatic complete placenta previa. Vitals reveal blood pressure of 129/81 mm Hg, heart rate of 87/min, respiratory rate of 15/min, and temperature of 37.9C (98.4F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of sogc placenta previa elective cesarean section delivery timing. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
    "options": [
      {
        "text": "Empiric broad-spectrum antifungal therapy as sole medical intervention",
        "correct": false,
        "explanation": "Incorrect: Antifungal therapy is inappropriate in the absence of documented microbiological or radiological evidence of invasive fungal disease."
      },
      {
        "text": "Intravenous loop diuretic administration in a hypovolemic or hypotensive patient",
        "correct": false,
        "explanation": "Incorrect: Administering potent loop diuretics during hypoperfusion exacerbates circulatory collapse and accelerates ischemic tubular injury."
      },
      {
        "text": "High-flow oxygen therapy via non-rebreather mask in acute hypercapnic respiratory failure",
        "correct": false,
        "explanation": "Incorrect: Uncontrolled high FiO2 in hypercapnic chronic lung disease abolishes hypoxic respiratory drive, precipitating carbon dioxide narcosis."
      },
      {
        "text": "Empiric aminoglycoside monotherapy for atypical community-acquired respiratory infection",
        "correct": false,
        "explanation": "Incorrect: Aminoglycosides lack reliable tissue penetration and intracellular activity against atypical respiratory organisms such as Mycoplasma."
      },
      {
        "text": "Planned delivery at 36+0 to 37+6 weeks gestation in stable asymptomatic complete placenta previa",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is planned delivery at 36+0 to 37+6 weeks gestation in stable asymptomatic complete placenta previa. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for SOGC Placenta Previa Elective Cesarean Section Delivery Timing.\\n\\nClinical Discussion: This clinical presentation corresponds to SOGC Placenta Previa Elective Cesarean Section Delivery Timing. The cornerstone of management involves planned delivery at 36+0 to 37+6 weeks gestation in stable asymptomatic complete placenta previa. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
